arguments.command:
python3 - <<'PY'
from openpyxl import load_workbook

# Validate only specified ranges modified by checking they are formulas and others not touched isn't easy.
# We'll at least ensure all target ranges have formulas.
wb=load_workbook('/root/output/result.xlsx', data_only=False)
ws=wb['Task']

# check ranges
ranges=[('H',12,17),('H',19,24),('H',26,31),('H',35,40),('H',42,47),('H',50,50)]
cols=['H','I','J','K','L']

def assert_formula(addr):
    v=ws[addr].value
    if not (isinstance(v,str) and v.startswith('=')):
        raise AssertionError(f'{addr} not formula: {v!r}')

# lookup blocks
for row in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for col in cols:
        assert_formula(f'{col}{row}')

# headroom
for row in range(35,41):
    for col in cols:
        assert_formula(f'{col}{row}')

# stats
for row in range(42,48):
    for col in cols:
        assert_formula(f'{col}{row}')

# weighted mean
for col in cols:
    assert_formula(f'{col}50')

print('All target cells contain formulas.')
PY

